def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    vowel_shift = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 's'}
    encoded_message = []

    for char in message:
        if char.lower() in vowels:
            if char.isupper():
                encoded_message.append(vowel_shift[char.lower()].upper())
            else:
                encoded_message.append(vowel_shift[char.lower()].lower())
        else:
            if char.isupper():
                encoded_message.append(char.lower())
            else:
                encoded_message.append(char.upper())

    return ''.join(encoded_message)

# Test cases
print(encode('test'))  # 'TGST'
print(encode('This is a message'))  # 'tHKS KS C MGSSCGG'
